'use client'

import { type NodeId, type RunState, type DeskCase } from '@/lib/run'
import { Icon, NODE_META } from '../meta'

const POS: Record<NodeId, [number, number]> = { complaint: [24, 28], intake: [324, 28], orchestrator: [324, 208], investigator: [24, 400], policy: [324, 400], resolver: [624, 400], human: [624, 600], outcome: [324, 800] }
const JOB: Record<NodeId, string> = { complaint: 'The original request', intake: 'Identify the right payment', orchestrator: 'Choose the next step from evidence', investigator: 'Establish where the money went', policy: 'Determine the rule and amount owed', resolver: 'Plan actions · validate · execute', human: 'Review actions outside automatic authority', outcome: 'Inspect the result and its proof' }
export default function WorkflowMap({ run, kase, selected, onSelect, onEdge }: { run: RunState; kase: DeskCase; selected: NodeId | null; onSelect: (n: NodeId) => void; onEdge: (edge: string) => void }) {
  const edges = Object.entries(run.edges).filter(([, state]) => state === 'active' || state === 'taken')
  if (run.nodes.intake.status !== 'idle' && run.nodes.intake.status !== 'skipped') {
    edges.push(['complaint>intake', run.nodes.intake.status === 'running' ? 'active' : 'taken'])
    if (run.nodes.orchestrator.status !== 'idle' && run.nodes.orchestrator.status !== 'skipped') edges.push(['intake>orchestrator', 'taken'])
  }
  return <div className="workflow-scroll" aria-label="Agent workflow. Select an agent to inspect its evidence."><div className="workflow-map">
    <svg className="workflow-lines" viewBox="0 0 900 960" aria-label="Recorded routing decisions">
      {edges.map(([edge, state]) => {
        const [from, to] = edge.split('>') as NodeId[]
        if (!POS[from] || !POS[to]) return null
        const [x, y] = POS[from], [tx, ty] = POS[to]
        const horizontal = y === ty
        const d = horizontal ? `M ${x + 250} ${y + 66} L ${tx} ${ty + 66}` : `M ${x + 125} ${y + 132} C ${x + 125} ${y + 165}, ${tx + 125} ${ty - 35}, ${tx + 125} ${ty}`
        return <g key={edge} role="button" tabIndex={0} aria-label={`Inspect route ${edge}`} onClick={() => onEdge(edge)} onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onEdge(edge) } }}><path d={d} fill="none" stroke="transparent" strokeWidth="20" /><path d={d} fill="none" className={state === 'active' ? 'route-active' : 'route-taken'} strokeWidth="2" /><title>{edge.replace('>', ' → ')} · {state}</title></g>
      })}
    </svg>
    {(Object.keys(POS) as NodeId[]).map(id => {
      const st = run.nodes[id]; const [left, top] = POS[id]
      const calls = run.steps.filter(s => s.node === id && s.kind === 'call')
      const waiting = id === 'human' && run.phase === 'awaiting'
      const label = id === 'complaint' ? kase.channel_label : NODE_META[id].label
      const state = waiting ? 'waiting' : st.status
      const outcome = id === 'outcome' && run.outcome
      return <button key={id} style={{ left, top }} onClick={() => onSelect(id)} aria-pressed={selected === id} className={`agent-card agent-${state} ${selected === id ? 'agent-selected' : ''}`}>
        <div className="flex items-center gap-2"><span className="agent-icon"><Icon name={id} /></span><span className="font-semibold text-[14px]">{label}</span><span className="ml-auto state-dot" /></div>
        <p className="mt-3 text-[12px] leading-5 line-clamp-2 text-slate-500">{outcome ? outcome.headline : st.activity || JOB[id]}</p>
        <div className="mt-2 flex items-center justify-between text-[10px] uppercase tracking-wider font-semibold"><span>{state === 'idle' ? 'Not started' : state === 'skipped' ? 'Not required' : state === 'done' ? 'Recorded' : state === 'running' ? 'Working' : 'Needs attention'}</span><span className="text-slate-400">{calls.length ? `${calls.length} calls ↗` : 'Inspect ↗'}</span></div>
      </button>
    })}
    {kase.status === 'NEEDS_INFO' && <button className="workflow-branch" style={{ left: 624, top: 208 }} onClick={() => onSelect('complaint')}><Icon name="complaint" /><b>Waiting for customer</b><span>{run.outcome?.customer_message || 'A detail is needed before investigation can continue.'}</span></button>}
    {(kase.status === 'FAILED' || kase.status === 'ESCALATED') && <button className="workflow-branch" style={{ left: 24, top: 600 }} onClick={() => onSelect('outcome')}><Icon name="guard" /><b>{kase.status === 'FAILED' ? 'Run interrupted' : 'Specialist review'}</b><span>{kase.headline}</span></button>}
    <div className="absolute left-6 bottom-3 text-[11px] text-slate-400">Connections show recorded handoffs. Unused agents remain available for inspection.</div>
  </div></div>
}
