    : interrupted ? 'Read the recorded result and any confirmed actions. Further review is required before the case can close.'
    : ended ? 'The resolution panel records what happened. Inspect any agent for its evidence or return to the customer conversation.'
    : 'Select an agent to inspect its work. Follow live returns to the current step. This guide follows the actual route, including skipped agents.'
  return (
    <section aria-label="Case journey guide" className="shrink-0 border-b border-blue-100 bg-blue-50/70 px-5 py-4">
      <div className="flex items-start justify-between gap-3">
        <ol aria-label="Case journey" className="flex flex-wrap gap-x-4 gap-y-2 text-[10px] font-semibold uppercase tracking-wider">
