  if (!plan || plan.error || !plan.rows.length) return <Text>Model data is unavailable. Open the operating plan to inspect it.</Text>;
  const series = (label) => plan.series.find(s => s.label === label || s.variable === label);
  const val = (row, label) => row[series(label)?.key];
  const last = plan.rows[plan.rows.length - 1];
  const cashSeries = series('Ending cash INR');
  const revenue = plan.rows.reduce((total, row) => total + (val(row, 'Total revenue INR') || 0), 0);
  const firstGap = plan.rows.find(row => val(row, 'Ending cash INR') < 0);
  const money = value => '₹' + (value / 100000).toFixed(2) + ' lakh';
  const gap = Math.max(0, -val(last, 'Ending cash INR'));
  return <Col style={{ gap: 24 }}>
    <Col style={{ gap: 6 }}><Text variant="heading">Validate the pilot before scaling the team</Text><Text variant="soft">DisputePro · October 2026–September 2027 · INR · editable planning assumptions</Text></Col>
    <Grid columns={3} minColumnWidth={220}>
      <Stat label="12-month revenue" value={money(revenue)} />
      <Stat label="Banks at September 2027" value={String(val(last, 'Active banks'))} />
      <Stat label="September funding gap" value={money(gap)} positive={gap === 0} />
    </Grid>
    <Divider />
    <Col style={{ gap: 8 }}><Text variant="title">Cash after collections and operating costs</Text><Chart height={300} options={{ data: plan.rows, series: [{ type: 'line', xKey: 'date', yKey: cashSeries.key, yName: 'Ending cash · INR', marker: { enabled: false }, strokeWidth: 2 }], legend: { enabled: false } }} /></Col>
    <Text>{firstGap ? 'Cash first turns negative in ' + firstGap.date + '. Reduce fixed costs, secure pilot payments earlier, or arrange funding before this point.' : 'Cash stays positive within this modeled horizon. Revisit sales and delivery assumptions before committing spend.'}</Text>
    <Grid columns={2} minColumnWidth={280}>
      <Col style={{ gap: 8 }}><Text variant="title">Pricing and delivery</Text><Text>Bank subscription plus usage overage and a one-time onboarding fee. Delivery includes model allowance, infrastructure, human review and bank support.</Text></Col>
      <Col style={{ gap: 8 }}><Text variant="title">Research behind the sales cycle</Text><Text>Crustdata returned a bank record, ambiguous Ujjivan candidates and an Equitas ATM listing. Plan a limited enterprise pilot; these are not customers or proven demand.</Text></Col>
    </Grid>
    <Text variant="soft">Use the scenario selector for Base (Main), Downside and Upside. All model values come from saved cfo.ai formulas; commercial inputs are assumptions. Sandbox refunds are not company revenue.</Text>
  </Col>;
}
