          <div className={`bank-master n-${run.nodes.orchestrator.status}`}><div className="bank-agent-icon"><Icon name="orchestrator" size={22}/></div><div><div className="bank-agent-heading"><h4>Master agent</h4><span>{active?'Coordinating':outcome?'Run recorded':'Ready'}</span></div><p>{run.nodes.orchestrator.activity || 'Picks the next ledger entry and coordinates all three specialists.'}</p><small className="bank-model">{model}</small></div></div>
          <div className="bank-connectors"><span/><span/><span/></div>
          <div className="bank-specialists">{agents.map(a=>{const n=run.nodes[a.id];const steps=run.steps.filter(s=>s.node===a.id && !['think','turn'].includes(s.kind));const latest=steps.at(-1);return <article key={a.id} className={`bank-agent n-${n.status}`}><div className="bank-agent-top"><span className="bank-agent-icon"><Icon name={a.id} size={20}/></span><span className="bank-agent-number">{a.number}</span><span className="bank-agent-state">{n.status==='running'?'Working':n.status==='done'?'Done':n.status==='waiting'?'Held':'Waiting'}</span></div><h4>{a.title}</h4><small className="bank-model">{model}</small><p>{n.status==='idle'||n.status==='skipped'?a.task:n.activity || a.task}</p><div className="bank-agent-output">{latest?<><span>{latest.kind==='call'?'SOURCE CHECK':'LATEST FINDING'}</span><strong>{latest.result || latest.detail || latest.title}</strong></>:<><span>{a.id==='policy'?'MANDATORY GATE':'NEXT STEP'}</span><strong>{a.id==='investigator'?'Core banking → NPCI → other bank':a.id==='policy'?'No financial action without policy clearance':'Complete · approval · investigate'}</strong></>}</div>{run.usage[a.id] && <div className="bank-token-count">{run.usage[a.id].llm_calls} model calls · {run.usage[a.id].input_tokens+run.usage[a.id].output_tokens} tokens</div>}</article>})}</div>
          <div className="bank-activity"><span className={active?'bank-dot':''}/><strong>{active?'Live activity':outcome?'Recorded activity':'Ready to begin'}</strong><p>{run.steps.at(-1)?.title || 'Press Run agents. The master picks the first transaction automatically.'}</p><span>{run.steps.filter(s=>s.kind==='call').length} source calls</span></div>
        </section>
        <section className={`bank-governance ${currentAudit?.status==='hold'?'held':''}`} aria-label="Mandatory RBI governance"><div className="bank-governance-title"><Icon name="policy" size={21}/><div><h3>RBI governance <span>{currentAudit ? currentAudit.status==='passed'?'Passed':'Hold':'Mandatory'}</span></h3><p>{currentAudit?.reason || 'Policy must pass before any refund or network action can execute.'}</p></div></div><div className="bank-policy-facts"><div><small>APPLICABILITY</small><strong>{currentAudit?.tat || (currentAudit?'Review required':c?.tat_days?`T+${c.tat_days} · to verify`:'Pending')}</strong></div><div><small>COMPENSATION</small><strong>{currentAudit ? rs(currentAudit.compensation_paise) : 'To calculate'}</strong></div><a href="https://rbi.org.in/commonman/English/scripts/Notification.aspx?Id=3074" target="_blank" rel="noreferrer">RBI circular ↗</a></div>{currentAudit && <details><summary>Inspect governance record</summary><p>{currentAudit.rule}</p><ul>{currentAudit.checks.map(x=><li key={x}>{x}</li>)}</ul><p>Checked {date(currentAudit.checked_at,true)}{currentAudit.deadline_at && ` · Deadline ${date(currentAudit.deadline_at,true)}`}</p></details>}</section>
        <section className="bank-results" aria-label="Actions and resolution"><div className="bank-section-heading"><div><p className="bank-kicker">THE OUTCOME</p><h3>Actions & resolution</h3></div><span>{outcome ? `${outcome.ops?.seconds ?? 0}s recorded` : 'Awaiting agent decisions'}</span></div>
          {c?.status==='NEEDS_YOU' && <div className="bank-approval"><div><h4>Human approval required</h4><p>{outcome?.human_reason || 'Review the proposed actions before authorizing payment.'} No proposed money movement has executed.</p></div><div className="bank-review-fields"><label>Reviewer<input value={reviewer} onChange={e=>setReviewer(e.target.value)} maxLength={80}/></label><label>Review note<input value={reason} onChange={e=>setReason(e.target.value)} placeholder="Required when sending to investigation" maxLength={500}/></label></div><div className="bank-review-buttons"><button disabled={busy || !!ledger?.queue.active_case_id || reviewer.trim().length<2} onClick={()=>decide(true)}>Approve displayed actions</button><button disabled={busy || !!ledger?.queue.active_case_id || !reason.trim() || reviewer.trim().length<2} onClick={()=>decide(false)}>Send to investigation</button></div>{ledger?.queue.active_case_id && <small>Pause the queue and wait for the current case to finish before approving.</small>}</div>}
          <div className="bank-action-flow">{outcome?.actions?.length ? outcome.actions.map((a,i)=><article className={`bank-action a-${a.state}`} key={`${a.type}-${i}`}><div><span>{String(i+1).padStart(2,'0')}</span><b>{pretty(a.state)}</b></div><h4>{pretty(a.type)}</h4><strong>{a.amount_paise?rs(a.amount_paise):'No money movement'}</strong><p>{a.note || a.reason}</p>{a.ref && <code>Receipt {a.ref}</code>}</article>) : <div className="bank-result-empty"><span>↳</span><div><h4>{c?.status==='ESCALATED'?'Financial action held':'A receipt for every decision'}</h4><p>{outcome?.summary || 'Validated actions, approval decisions and execution references will appear here.'}</p></div></div>}</div>{outcome && <div className="bank-receipt"><span>CASE RECEIPT</span><p>{outcome.summary}</p><code>{c?.run_id}</code></div>}
        </section>
        <section className="bank-evidence" aria-label="Source evidence"><div className="bank-section-heading"><div><p className="bank-kicker">VERIFY THE WORK</p><h3>Source evidence</h3></div>{(run.traceUrl || outcome?.trace_url) && <a href={run.traceUrl || outcome?.trace_url} target="_blank" rel="noreferrer">Open neatlogs trace ↗</a>}</div><div className="bank-evidence-grid">{outcome?.findings?.evidence?.map((e,i)=><article key={i}><small>{e.source}</small><p>{e.fact}</p></article>)}</div><details className="bank-tool-log"><summary>Agent activity & source responses <span>{run.steps.length} events</span></summary>{run.steps.length ? run.steps.filter(s=>s.kind!=='think').map(s=><details key={s.id}><summary><span>{(s.t/1000).toFixed(1)}s · {s.node}</span> {s.title}<b>{s.status}</b></summary><p>{s.result || s.detail}</p>{s.http && <code>{s.http.method} {s.http.path} {s.http.status}</code>}{s.data!==undefined && <pre>{JSON.stringify(s.data,null,2)}</pre>}</details>):<p>Source responses appear when the investigation starts.</p>}</details><p className="bank-evidence-note">Sandbox bank and network adapters · Actual model calls and tool responses are recorded. Entire, cfo.ai and Crustdata support the build and business plan; they are not payment evidence. <Link href="/evidence">View sponsor proof ↗</Link></p></section>
      </main>
    </div>
  </div>
}
